import urllib.request, concurrent.futures, hashlib, json
base='https://raw.githubusercontent.com/openmm/openmm/53770948682c40bd460b39830d4e0f0fd3a4b868/'
urls={
'benchmark':base+'examples/benchmark.py',
'pdb':base+'examples/5dfr_solv-cube_equil.pdb',
'amber99sb':base+'wrappers/python/openmm/app/data/amber99sb.xml',
'TIP3P':base+'wrappers/python/openmm/app/data/tip3p.xml',
'pypi':'https://pypi.org/pypi/openmm/8.2.0/json',
'cuda_pypi':'https://pypi.org/pypi/OpenMM-CUDA-12/8.2.0/json',
'properties':'https://docs.openmm.org/8.2.0/userguide/library/04_platform_specifics.html',
}
def fetch(kv):
 k,u=kv
 try:
  b=urllib.request.urlopen(u,timeout=25).read()
  d={'name':k,'url':u,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
  if k=='benchmark': d['code']=b.decode()
  if k=='pdb': d['atoms']=sum(x.startswith((b'ATOM  ',b'HETATM')) for x in b.splitlines())
  if k in ('pypi','cuda_pypi'):
   j=json.loads(b);d['requires_dist']=j['info']['requires_dist']; d['requires_python']=j['info']['requires_python'];d['wheels']=[{'name':x['filename'],'bytes':x['size'],'sha256':x['digests']['sha256']} for x in j['urls'] if 'manylinux' in x['filename']]
  if k=='properties':
   s=b.decode(); i=s.find('DeterministicForces');d['determinism_excerpt']=s[i:i+1600]
  return d
 except Exception as e:return {'name':k,'error':str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=7) as ex:
 for d in ex.map(fetch,urls.items()):print(json.dumps(d))
PY"

